-- IGM UPDATE AND DO ISSUE — docs/DESIGN-UPDATE-2026-10-04.md §4
-- ===========================================================================
--
-- Two new tables and one enum, both for inbound bookings only:
--
--   igm_update       the HBL No and the uploaded IGM file (sheet `IGM Update`)
--   delivery_order   the DO letter: date, addressee, subject, body, and the
--                    printed copy (sheet `DO issue`)
--
-- Nothing existing is altered. The DDL was generated by `prisma migrate diff`;
-- the integrity, tenancy and audit statements below it are hand-written.
-- ===========================================================================

-- CreateEnum
CREATE TYPE "delivery_order_status" AS ENUM ('ISSUED', 'CANCELLED');

-- CreateTable
CREATE TABLE "igm_update" (
    "tenant_id" BIGINT NOT NULL,
    "id" BIGSERIAL NOT NULL,
    "shipment_id" BIGINT NOT NULL,
    "hbl_no" VARCHAR(64),
    "igm_file" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "igm_update_pkey" PRIMARY KEY ("id")
);

-- CreateTable
CREATE TABLE "delivery_order" (
    "tenant_id" BIGINT NOT NULL,
    "id" BIGSERIAL NOT NULL,
    "code" VARCHAR(32) NOT NULL,
    "series_year" INTEGER NOT NULL,
    "shipment_id" BIGINT NOT NULL,
    "issue_date" DATE NOT NULL,
    "addressee" TEXT NOT NULL,
    "subject" TEXT NOT NULL,
    "body" TEXT,
    "status" "delivery_order_status" NOT NULL DEFAULT 'ISSUED',
    "pdf_file" TEXT,
    "issued_by" BIGINT,
    "issued_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "cancelled_by" BIGINT,
    "cancelled_at" TIMESTAMPTZ(6),
    "cancel_reason" TEXT,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "created_at" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMPTZ(6) NOT NULL,
    "created_by" BIGINT,
    "updated_by" BIGINT,
    "deleted_at" TIMESTAMPTZ(6),

    CONSTRAINT "delivery_order_pkey" PRIMARY KEY ("id")
);

