-- ---------------------------------------------------------------- integrity
-- One live IGM row per booking; saving again updates it.
CREATE UNIQUE INDEX "igm_update_one_live_key"
  ON "igm_update"("tenant_id", "shipment_id")
  WHERE "deleted_at" IS NULL;

-- A saved row says something: the number, the file, or both.
ALTER TABLE "igm_update" ADD CONSTRAINT "igm_update_not_empty"
  CHECK ("hbl_no" IS NOT NULL OR "igm_file" IS NOT NULL);

-- One issued delivery order per booking. A cancelled one stays, numbered.
CREATE UNIQUE INDEX "delivery_order_one_issued_key"
  ON "delivery_order"("tenant_id", "shipment_id")
  WHERE "deleted_at" IS NULL AND "status" = 'ISSUED';

-- Cancelling says why, and when, and who.
ALTER TABLE "delivery_order" ADD CONSTRAINT "delivery_order_cancellation_ck"
  CHECK (
    "status" <> 'CANCELLED'
    OR ("cancelled_at" IS NOT NULL
        AND "cancelled_by" IS NOT NULL
        AND "cancel_reason" IS NOT NULL
        AND length(btrim("cancel_reason")) > 0)
  );

ALTER TABLE "delivery_order" ADD CONSTRAINT "delivery_order_text_not_blank"
  CHECK (length(btrim("addressee")) > 0 AND length(btrim("subject")) > 0);

-- ------------------------------------------------------------------ tenancy
-- The single-comparison form (20260917090000). app_staff_tenant() is NULL for
-- any non-staff session, so an agent or a customer reads nothing here.
ALTER TABLE "igm_update" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "igm_update"
  USING (tenant_id = app_staff_tenant())
  WITH CHECK (tenant_id = app_staff_tenant());

ALTER TABLE "delivery_order" ENABLE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON "delivery_order"
  USING (tenant_id = app_staff_tenant())
  WITH CHECK (tenant_id = app_staff_tenant());

GRANT SELECT, INSERT, UPDATE ON TABLE "igm_update" TO ff_app;
GRANT USAGE, SELECT ON SEQUENCE "igm_update_id_seq" TO ff_app;
GRANT SELECT, INSERT, UPDATE ON TABLE "delivery_order" TO ff_app;
GRANT USAGE, SELECT ON SEQUENCE "delivery_order_id_seq" TO ff_app;

-- §4 rule 7: the audit trail is a trigger, so a write from any path is caught.
CREATE TRIGGER "igm_update_audit"
  AFTER INSERT OR UPDATE OR DELETE ON "igm_update"
  FOR EACH ROW EXECUTE FUNCTION app_audit_row();
CREATE TRIGGER "delivery_order_audit"
  AFTER INSERT OR UPDATE OR DELETE ON "delivery_order"
  FOR EACH ROW EXECUTE FUNCTION app_audit_row();
